const rows = $input.all().map(function(item) {
  return item.json;
});

function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function number(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return num.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

function percent(value) {
  if (value === null || value === undefined || value === "") return "N/A";
  const num = Number(value);
  if (Number.isNaN(num)) return escapeHtml(value);
  return (num * 100).toFixed(1) + "%";
}

function signalClass(value) {
  const v = String(value || "").toLowerCase();
  if (v === "yes" || v === "likely") return "flag-bad";
  if (v === "unknown") return "flag-neutral";
  return "flag-good";
}

function formatCell(row, key) {
  if (key === "visits_l6m" || key === "converted_l6m" || key === "missing_recommended_tag_count" || key === "weeks_with_traffic_l6m") return number(row[key]);
  if (key === "cvr_l6m" || key === "recommended_tag_coverage" || key === "five_plus_review_coverage" || key === "current_availability" || key === "current_mrpi" || key === "current_wsi") return percent(row[key]);
  return escapeHtml(row[key]);
}

function makeTable(title, tableRows, columns) {
  if (!Array.isArray(tableRows) || tableRows.length === 0) {
    return `<h2>${escapeHtml(title)}</h2><p><em>No rows returned.</em></p>`;
  }

  const headerHtml = columns.map(function(col) {
    return `<th>${escapeHtml(col.label)}</th>`;
  }).join("");

  const bodyHtml = tableRows.map(function(row) {
    const cells = columns.map(function(col) {
      const value = formatCell(row, col.key);
      const className = col.flag ? signalClass(row[col.key]) : "";
      return `<td class="${className}">${value}</td>`;
    }).join("");

    return `<tr>${cells}</tr>`;
  }).join("");

  return `
    <h2>${escapeHtml(title)}</h2>
    <table>
      <thead><tr>${headerHtml}</tr></thead>
      <tbody>${bodyHtml}</tbody>
    </table>
  `;
}

const storyColumns = [
  { label: "SKU", key: "sku" },
  { label: "Supplier", key: "requested_supplier" },
  { label: "Original Issue", key: "requested_issue" },
  { label: "Visits L6M", key: "visits_l6m" },
  { label: "CVR L6M", key: "cvr_l6m" },
  { label: "Pricing Suppression?", key: "pricing_suppression_signal", flag: true },
  { label: "Missing Tags?", key: "missing_tags", flag: true },
  { label: "Has 5+ Reviews?", key: "has_five_plus_reviews", flag: true },
  { label: "Traffic Story", key: "traffic_story" },
  { label: "Conversion Story", key: "conversion_story" },
  { label: "Recommended Action", key: "recommended_action" }
];

const evidenceColumns = [
  { label: "SKU", key: "sku" },
  { label: "Status", key: "prstatusname" },
  { label: "Status Reason", key: "skustatusreasonname" },
  { label: "Pricing Evidence", key: "pricing_suppression_reason" },
  { label: "Tag Coverage", key: "recommended_tag_coverage" },
  { label: "Missing Tag Count", key: "missing_recommended_tag_count" },
  { label: "5+ Review Coverage", key: "five_plus_review_coverage" },
  { label: "Availability", key: "current_availability" },
  { label: "MRPI", key: "current_mrpi" },
  { label: "WSI", key: "current_wsi" }
];

const merchColumns = [
  { label: "SKU", key: "sku" },
  { label: "SKU Name", key: "sku_full_name" },
  { label: "Current Supplier(s)", key: "supplier_names" },
  { label: "Marketing Category", key: "mkcname" },
  { label: "Class", key: "clinternalref" },
  { label: "Price Group", key: "pricegroupname" },
  { label: "Ship Via", key: "svclassname" },
  { label: "Castlegate", key: "incastlegatename" },
  { label: "MAP", key: "prhasmapname" }
];

const flaggedCount = rows.filter(function(row) {
  return row.pricing_suppression_signal === "Yes" ||
    row.pricing_suppression_signal === "Likely" ||
    row.missing_tags === "Yes" ||
    row.has_five_plus_reviews !== "Yes";
}).length;

const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #222;
      line-height: 1.4;
    }

    h1 {
      background: #1f4e79;
      color: white;
      padding: 14px;
      border-radius: 6px;
    }

    h2 {
      margin-top: 28px;
      color: #1f4e79;
      border-bottom: 2px solid #1f4e79;
      padding-bottom: 4px;
    }

    .summary {
      background: #f3f7fb;
      border-left: 4px solid #1f4e79;
      padding: 12px;
      margin-bottom: 18px;
    }

    table {
      border-collapse: collapse;
      width: 100%;
      margin-bottom: 22px;
      font-size: 12px;
    }

    th {
      background: #eaf2f8;
      color: #111;
      text-align: left;
      padding: 8px;
      border: 1px solid #ccc;
    }

    td {
      padding: 8px;
      border: 1px solid #ddd;
      vertical-align: top;
    }

    tr:nth-child(even) {
      background: #f9f9f9;
    }

    .flag-bad {
      color: #8a1f11;
      font-weight: bold;
      background: #fdecea;
    }

    .flag-good {
      color: #1f6f3a;
      font-weight: bold;
      background: #edf7ed;
    }

    .flag-neutral {
      color: #7a5c00;
      font-weight: bold;
      background: #fff8db;
    }
  </style>
</head>
<body>
  <h1>Cathay & Sunham SKU Deep Dive</h1>
  <div class="summary">
    <p><strong>What this report answers:</strong> For each SKU, it shows L6M visits, L6M CVR, whether pricing suppression is signaled, whether tags are missing, whether the SKU has 5+ reviews, and a plain-English traffic/conversion story.</p>
    <p><strong>Rows with at least one blocker:</strong> ${flaggedCount} of ${rows.length}</p>
  </div>
  ${makeTable("SKU Story and Action Plan", rows, storyColumns)}
  ${makeTable("Evidence Behind the Story", rows, evidenceColumns)}
  ${makeTable("Catalog Context", rows, merchColumns)}
</body>
</html>
`;

return [{ json: { htmlBody } }];
